use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let chars = line.chars().collect::<Vec<char>>()
        let n = chars.len()
        let mut fields: Vec<string> = []
        let mut cur = ""
        let mut inq = false
        let mut i = 0
        while i < n {
            let c = chars[i]
            if inq {
                if c == '"' {
                    if i + 1 < n && chars[i + 1] == '"' {
                        cur = cur + "\""
                        i += 1
                    } else {
                        inq = false
                    }
                } else {
                    cur = cur + c.to_string()
                }
            } else if c == '"' {
                inq = true
            } else if c == ',' {
                fields.push(cur)
                cur = ""
            } else {
                cur = cur + c.to_string()
            }
            i += 1
        }
        fields.push(cur)
        let mut out = "${fields.len()}: "
        let mut first = true
        for f in fields {
            if !first { out = out + "|" }
            first = false
            out = out + "[" + f + "]"
        }
        println(out)
    }
}

